// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2000, "7-8", [{"author":"Е. Муравенко","question":"Какое слово можно составить из тех же букв, что и слово <em>ромашка</em> (каждую букву нужно использовать столько раз, сколько она встречается в данном слове)?","choices":["<em>мошкара</em>","<em>кошмар</em>","<em>морошка</em>","<em>кармашек</em>","<em>гармошка</em>."],"key":"А","review":["Буквы ромашки","В слове «ромашка» две буквы а, а буквы р, о, м, ш, к встречаются по одному разу.","В слове «мошкара» набор тот же: м-о-ш-к-а-р-а. В слове «кошмар», например, не хватает второй а."]},{"author":"М. Кронгауз","question":"Сколько из перечисленных слов можно поставить вместо многоточия в предложение <em>... шёл по лесу</em>: <em>конь, лошадь, мужик, староста, чукча</em>?","choices":["одно","два","три","четыре","все."],"key":"Г","review":["Кто шёл по лесу","Форма «шёл» согласуется с подлежащим в мужском роде. Окончание существительного на -а не обязательно означает женский род.","Шёл конь, мужик, староста или чукча. Для слова «лошадь» нужна форма «шла». Получаем четыре случая."]},{"author":"К. Кноп","question":"Посмотрите на список слов: <em>варе...ка, коври...ка, деревя...ка, костя...ка.</em> В скольких из них пропущена буква <em>ш</em> (а не <em>ж</em>)?","choices":["0","1","2","3","4."],"key":"В","review":["Буква перед «ка»","Проверяем согласный формой, где после него слышится гласный: «варежек», «коврижек», «деревяшек», «костяшек».","Букву ш пишем в словах «деревяшка» и «костяшка», букву ж — в двух других."]},{"author":"М. Кронгауз","question":"Найдите подлежащие во фразах: (1) <em>Тореро надел сомбреро</em> и (2) <em>Сомбреро надел тореро</em>.","choices":["(1) <em>тореро</em> и (2) <em>сомбреро</em>","(1) <em>сомбреро</em> и (2) <em>тореро</em>","(1) <em>тореро</em> и (2) <em>тореро</em>","(1) <em>сомбреро</em> и (2) <em>сомбреро</em>","подлежащих нет."],"key":"В","review":["Кто надел шляпу","Исполнитель действия — человек, а шляпа — предмет, который он надевает. Ни «тореро», ни «сомбреро» не изменяются по падежам.","Перестановка слов не меняет исполнителя. В обоих предложениях подлежащее «тореро»."]},{"author":"Е. Муравенко","question":"В скольких глаголах из приведённого списка можно по-разному поставить ударение: <em>вычитать, прочитать, рассыпать, выкупать, искупать, вырезать, отрезать</em>?","choices":["в трёх","в четырёх","в пяти","в шести","в семи."],"key":"В","review":["Два ударения","Сравни «вы́читать сведения» и «вычита́ть из числа», «рассы́пать крупу» и «рассыпа́ть понемногу», «вы́купать ребёнка» и «выкупа́ть билет».","Ещё две пары: «вы́резать — выреза́ть» и «отре́зать — отреза́ть». У «прочитать» и «искупать» второго такого варианта нет. Итого пять."]},{"author":"М. Кронгауз","question":"Среди слов <em>ель, заяц, лягушка, огурец, трава</em> одно — по смыслу лишнее. Какое? Сравните обычные для них цвета.","choices":["<em>ель</em>","<em>заяц</em>","<em>лягушка</em>","<em>огурец</em>","<em>трава</em>."],"key":"Б","review":["Общий цвет","Ищем признак, который обычно можно назвать у ели, лягушки, огурца и травы. В привычных описаниях они зелёные.","У зайца обычная окраска серая, бурая или белая. По этому признаку он отличается от остальных."],"reviewedEdition":true},{"author":"М. Кронгауз","question":"Дано толкование слова: «издавать громкие пронзительные высокие звуки». Какое слово подходит под это определение?","choices":["<em>визжать;</em>","<em>кричать</em>","<em>пищать</em>","<em>орать</em>","ни одно из названных."],"key":"А","review":["Словарное определение","Кричать можно низким голосом, а пищать можно тихо. Эти глаголы не передают сразу все признаки, названные в определении.","«Визжать» обозначает именно громкий, резкий и высокий звук."]},{"author":"Е. Муравенко","question":"Какие из приведённых слов родственны слову <em>нос</em>: 1) <em>поднос</em>, 2) <em>носильщик</em>, 3) <em>носовой</em>, 4) <em>носик</em>, 5) <em>обноски</em>?","choices":["все","1, 2, 3, 4","1, 4","1, 2, 4","3, 4."],"key":"Д","review":["Два разных «нос»","Слова «поднос», «носильщик» и «обноски» связаны с глаголом «носить». Совпадения букв недостаточно для родства с названием части лица.","«Носовой» и «носик» образованы от «нос». Это слова под номерами 3 и 4."]},{"author":"К. Кноп","question":"Посмотрите на список слов: <em>фанера, пастель, постель, кафе, кофе, купе</em>. В скольких из них буква <em>е</em> не смягчает предыдущий согласный звук?","choices":["0","1","2","3","4."],"key":"Г","review":["Твёрдый перед «е»","В принятом для задания произношении в словах «пастель», «кафе» и «купе» перед е слышится твёрдый согласный: т, ф, п.","В «фанера», «постель» и «кофе» согласный перед е мягкий. Получаем три слова первой группы."]},{"author":"И. Рубанов","question":"Город Великие Луки получил такое название из-за того, что:","choices":["славился мастерами по изготовлению луков","в его окрестностях лук вырастал особенно крупным","город прославили его основатель Лука Великий и его сын Лука Лукич","в нем находится штаб-квартира компании \"Лукойл\"","река, на которой он стоит, имеет большие излучины."],"key":"Д","review":["Название города","Старое значение «лука» — изгиб, излучина. Вспомни также слово «лукоморье», связанное с изгибом берега.","Великие Луки стоят на реке Ловати с большими излучинами. Этим названием объясняется вариант о форме реки."]},{"author":"Е. Муравенко","question":"До орфографической реформы 1917–1918 гг. каждое прилагательное имело в именительном падеже множественного числа две разные формы, например: <em>новые учебники</em>, но <em>новыя книги</em>; <em>старые ботинки</em>, но <em>старыя письма и телеграммы</em>; <em>светлые классы</em>, но <em>светлыя окна</em>. Как до орфографической реформы записывались словосочетания <em>красивые вазы</em> и <em>просторные поля</em>?","choices":["<em>красивыя вазы</em>, <em>просторныя поля</em>","<em>красивые вазы</em>, <em>просторныя поля</em>","<em>красивыя вазы</em>, <em>просторные поля</em>","<em>красивые вазы</em>, <em>просторные поля</em>","ни один из вариантов (А)–(Г) не верен."],"key":"А","review":["Старинные окончания","В примерах перед существительными мужского рода стоит -ые, а перед существительными женского и среднего рода — -ыя.","«Ваза» женского рода, «поле» среднего. По старому правилу пишем «красивыя вазы, просторныя поля»."]},{"author":"Е. Муравенко","question":"До начала XVIII века в русском языке числа обозначались буквами, например: ТЛЕ – 335, РМД – 144, ФЛВ – 532. Как, по-вашему, записывалось число 225?","choices":["ВВФ","ВВЕ","СКЕ","СКФ","ВНФ."],"key":"В","review":["Буквы вместо цифр","В образце 335 буквы Т и Л обозначают разные разряды, а последняя Е обозначает 5. Для 225 тоже нужен знак Е в конце.","Одинаковая цифра в сотнях и десятках обозначается разными буквами: С — 200, К — 20. Получаем СКЕ."]},{"author":"Е. Муравенко","question":"Сколько существительных из приведённого списка совпадают по форме с деепричастиями: <em>срыв, перерыв, покров, лев, сев, зев</em>?","choices":["2","3","4","5","6."],"key":"Б","review":["Существительное или действие","«Срыв» можно прочитать как «срыв бугор», «перерыв» — как «перерыв землю», «сев» — как «сев на стул». В этих примерах названо добавочное действие.","Существительные «покров», «лев» и «зев» такой формы деепричастия не дают. Итого три совпадения."]},{"author":"И. Рубанов","question":"Как образуется форма родительного падежа множественного числа от слова <em>кочерга</em>?","choices":["<em>кочерёг</em>","<em>кочергов</em>","<em>кочерг</em>","<em>кочерыг</em>","у этого слова нет множественного числа."],"key":"А","review":["Несколько кочерёг","Нужна форма для сочетания «нет нескольких …». Сначала подберём множественное число: одна кочерга — кочерги.","В родительном множественного появляется беглая гласная: «нет кочерёг»."]},{"author":"Е. Муравенко и И. Рубанов","question":"Из пяти приведённых ниже слов только одно имеет единственное значение, а каждое из остальных употребляется по крайней мере в двух разных смыслах. Какое же слово имеет единственное значение?","choices":["<em>полька</em>","<em>француженка</em>","<em>чешка</em>","<em>финка</em>","<em>голландка</em>."],"key":"Б","review":["Жительница или предмет","Полька бывает танцем, чешка — обувью для занятий, финка — ножом, голландка — печью. Те же формы могут обозначать женщин.","Слово «француженка» из этого ряда обозначает только женщину по национальности в рассмотренных общеупотребительных значениях."]},{"author":"А. Тубман","question":"Посмотрите на список слов: <em>жеребёнок, опёнок, телёнок, зайчонок</em>. От какого из них множественное число в современном <em>литературном</em> русском языке образуется двумя способами?","choices":["<em>жеребёнок</em>","<em>опёнок</em>","<em>телёнок</em>","<em>зайчонок</em>","ни от какого."],"key":"Б","review":["Множественное число","Жеребёнок — жеребята, телёнок — телята, зайчонок — зайчата. У грибного названия есть две нормативные формы.","Можно сказать «опята» и «опёнки». Обе формы относятся к слову «опёнок»."]},{"author":"К. Кноп","question":"Посмотрите на список слов: <em>смягчение, легчайший, мягчайший, тягчайший</em>. В каком из них сочетание букв <em>гч</em> произносится иначе, чем в остальных трёх?","choices":["<em>смягчение</em>","<em>легчайший</em>","<em>мягчайший</em>","<em>тягчайший</em>","ни в каком."],"key":"Г","review":["Что слышно перед «ч»","В традиционном произношении «мягкий» и «лёгкий» перед к звучит х. Этот же согласный сохраняется в «смягчение», «мягчайший», «легчайший».","В «тягчайший» на месте г перед ч произносится к. В написании различия не видно."]},{"author":"М. Кронгауз","question":"Какие из перечисленных животных традиционно используются как сельскохозяйственные или служебные: <em>верблюд, корова, крокодил, крыса, собака</em>? Сколько таких названий в списке?","choices":["одно","два","три","четыре","все."],"key":"В","review":["Названия домашних животных","Считаем названия обычных одомашненных животных в их основном значении. Верблюд, корова и собака подходят.","Крокодил и крыса в этом перечне к традиционным сельскохозяйственным и служебным животным не относятся. Получаем три названия."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"Сколько глаголов из приведённого списка могут быть поняты и как формы изъявительного, и как формы повелительного наклонения: <em>носите, вынесите, пилите, колите, просите, распорите</em>?","choices":["2","3","4","5","6."],"key":"Б","review":["Сообщение или просьба","Можно сообщить «вы но́сите, пи́лите, про́сите» и попросить «носи́те, пили́те, проси́те». На письме в каждой паре буквы одинаковы.","Формам приказа «вынесите», «колите», «распорите» соответствуют другие написания во втором лице: «вынесете», «колете», «распорете». Подошли три слова."]},{"author":"Е. Муравенко","question":"Прочтите загадку, зашифрованную в ребусе, и найдите подходящую отгадку.","choices":["лапша","блины","картошка","хлеб","соль."],"key":"А","review":["Загадка на ложке","В начале ребуса нота си, буква д и «кит» без первой буквы дают «сидит». В конце к «нож» прибавляем «ки»: это «очки» без двух первых букв.","Смысл загадки: «Сидит на ложке, свесив ножки». С ложки свисают длинные полоски лапши."],"figure":{"condition":{"src":"assets/medvezhonok/2000/figures/7-8-20.webp","detailSrc":"assets/medvezhonok/2000/figures/7-8-20-detail.webp","alt":"Нота, буква, кит, ложка, весы, нож и очки со знаками ребуса.","pixelWidth":2297,"pixelHeight":380}}},{"author":"И. Рубанов","question":"Древнерусское слово <em>коло</em> означает «круг». Сколько в списке: <em>колесо, колотить, околица, колоть, кольцо, колея</em> — слов, имеющих со словом <em>коло</em> общий исторический корень?","choices":["1","2","3","4","5."],"key":"Г","review":["Семья слова «коло»","Ищи старую связь с кругом или движением колеса. Она видна в словах «колесо», «околица», «кольцо», «колея».","«Колоть» и «колотить» связаны с другими действиями. Получается четыре родственных слова."]},{"author":"Е. Муравенко","question":"Сколько различных смыслов имеет фраза <em>Знакомые учителя вернулись из командировки в Москву</em>?","choices":["2","3","4","6","8."],"key":"В","review":["Кто вернулся и откуда","«Знакомые учителя» — это либо знакомые нам преподаватели, либо знакомые одного учителя. У слова «учителя» разные ударения и падежи.","«В Москву» может называть место возвращения или направление прежней командировки. У каждого из двух составов участников есть два прочтения: 2 × 2 = 4."]},{"author":"Е. Муравенко","question":"Сколько общих звуков содержится в словах <em>друг</em> и <em>груздь</em>?","choices":["1","2","3","4","0."],"key":"Б","review":["Звуки двух слов","В «друг» конечное г оглушается и звучит как к. В «груздь» в конце слышны мягкие согласные, которых нет в первом слове.","Общие звуки — твёрдый р и гласный у. Буквы г и д встречаются в обоих написаниях, но это разные звуковые позиции."]},{"author":"И. Рубанов","question":"Гнедой конь – это:","choices":["коричневый, с чёрными гривой, хвостом и нижней частью ног","серый","черный","рыжеватый","белесый."],"key":"А","review":["Масть коня","Гнедая масть узнаётся по коричневому корпусу и тёмным гриве, хвосту и нижним частям ног. Оттенок корпуса бывает красноватым.","Выбираем описание коричневого коня с чёрными гривой и хвостом. Просто рыжая масть устроена иначе."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"Какие из перечисленных существительных являются одушевленными: 1) [плюшевый] <em>мишка</em>, 2) <em>игрушка</em>, 3) <em>валет</em>, 4) <em>девочка</em>, 5) <em>мертвец</em>?","choices":["4","4, 5","3, 4, 5","1, 2, 4, 5","1, 3, 4, 5."],"key":"Д","review":["Одушевлённость","Поставим слова во множественное число после «вижу». Получаем «вижу мишек, валетов, девочек, мертвецов», как в родительном падеже.","Только «вижу игрушки» совпадает с именительным. Грамматически одушевлены номера 1, 3, 4 и 5."]},{"author":"Е. Муравенко","question":"Иван выехал из Москвы в 8 утра 22 ноября, а приехал в Екатеринбург в 8 вечера 23 ноября. Оба времени указаны по московским часам. Как правильно сказать, сколько времени Иван ехал?","choices":["<em>полтора суток</em>","<em>полторы суток</em>","<em>полутора суток</em>","<em>полторы сутки</em>","ни один из вариантов (А)-(Г) не верен."],"key":"Д","review":["Как назвать длительность","У слова «сутки» нет обычного единственного числа. Формы «полтора» и «полторы» не дают нормативного сочетания с этим словом в именительном падеже.","Для промежутка в 36 часов подойдёт «полтора дня». Среди первых четырёх вариантов нормативной формулировки нет."],"reviewedEdition":true},{"author":"Е. Муравенко","question":"Какие из перечисленных слов являются числительными: 1) <em>оба</em>, 2) <em>два</em>, 3) <em>двойка</em>, 4) <em>пара</em>, 5) <em>двое</em>?","choices":["2","2, 3, 5","2, 5","1, 2, 5","1, 2, 3, 4, 5."],"key":"Г","review":["Слова, которые считают","«Два» отвечает на вопрос «сколько?», «двое» и «оба» относятся к собирательным числительным в школьной классификации.","«Двойка» и «пара» — существительные, хотя их значения тоже связаны со счётом. Нужны номера 1, 2 и 5."]},{"author":"Е. Муравенко","question":"Сколькими способами можно в ряду букв <em>ПОДНИМИТЕПЕРЬЯ</em> расставить пробелы (не вставляя никаких знаков препинания), чтобы получилась фраза?","choices":["2","3","4","5","6."],"key":"Д","review":["Где поставить пробелы","С глаголом в начале получаются «поднимите перья» и «подними те перья». С началом «под ними» возможны «под ними те перья» и «под ними теперь я».","Ещё два прочтения начинаются с «под ним»: «под ним и те перья» и «под ним и теперь я». Всего шесть."]},{"author":"Е. Муравенко","question":"Найдите синоним устойчивого словосочетания <em>переливать из пустого в порожнее</em>:","choices":["<em>бить баклуши</em>","<em>вариться в собственном соку</em>","<em>трезвонить во все колокола</em>","<em>точить лясы</em>","<em>плевать в потолок</em>."],"key":"Г","review":["Разговор впустую","«Переливать из пустого в порожнее» можно о разговоре, который тянется без содержательного результата.","«Точить лясы» — вести пустую болтовню. «Бить баклуши» тоже относится к безделью, но не обязательно к разговору."]},{"author":"Е. Муравенко","question":"Есть ли в русском языке одушевленные существительные среднего рода?","choices":["нет","есть, и все они относятся ко 2-му склонению","есть, но ни одно из них не обозначает человека","есть, среди них есть слова, которые склоняются как прилагательные","есть, они образованы с помощью уменьшительного суффикса -<em>ишк</em>-."],"key":"Г","review":["Живое среднего рода","Проверяем слово в винительном множественного: «вижу животных, млекопитающих, насекомых». Эти существительные среднего рода склоняются по образцу прилагательных.","Существуют и другие модели, например «дитя». Значит, утверждать, что таких слов нет или все они второго склонения, нельзя."],"reviewedEdition":true}], {"year":2000,"grade":"7-8","tasksFile":"7-8.pdf","answersFile":"7-8-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2000.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
